package com.compcorp.commerce.batch;
import java.io.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.time.format.DateTimeParseException;import java.util.*;
public final class OrderCsvImporter{private OrderCsvImporter(){} public record Accepted(String orderId,String customer,String date,int quantity,BigDecimal amount){} public record Rejected(int line,String raw,String reason){} public record Result(List<Accepted> accepted,List<Rejected> rejected,BigDecimal total){}
 public static Result importFile(Path file)throws IOException{List<Accepted> ok=new ArrayList<>();List<Rejected> bad=new ArrayList<>();try(BufferedReader r=Files.newBufferedReader(file,StandardCharsets.UTF_8)){String header=r.readLine();if(header==null||!header.equalsIgnoreCase("order_id,customer,date,quantity,amount"))throw new IOException("Expected header: order_id,customer,date,quantity,amount");String line;int n=1;while((line=r.readLine())!=null){n++;try{String[] c=line.split(",",-1);if(c.length!=5)throw new IllegalArgumentException("Expected 5 columns");if(c[0].isBlank()||c[1].isBlank())throw new IllegalArgumentException("Missing order/customer");LocalDate.parse(c[2]);int qty=Integer.parseInt(c[3]);BigDecimal amount=new BigDecimal(c[4]);if(qty<1||amount.signum()<0)throw new IllegalArgumentException("Quantity must be positive and amount non-negative");ok.add(new Accepted(c[0],c[1],c[2],qty,amount));}catch(RuntimeException e){bad.add(new Rejected(n,line,e.getMessage()==null?"Invalid row":e.getMessage()));}}}BigDecimal total=ok.stream().map(Accepted::amount).reduce(BigDecimal.ZERO,BigDecimal::add);return new Result(List.copyOf(ok),List.copyOf(bad),total);}}
